148	  static func claude(data: Data, capturedAt: Date, now: Date) -> AgentQuotaSnapshot? {
149	    guard let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
150	      return nil
151	    }
152	    let limits = (root["rate_limits"] as? [String: Any]) ?? root
153	    var windows: [AgentQuotaWindow] = []
154	    if let value = decodeClaudeWindow(
155	      limits["five_hour"], kind: .fiveHour, duration: 5 * 60 * 60)
156	    {
157	      windows.append(value)
158	    }
159	    if let value = decodeClaudeWindow(
160	      limits["seven_day"], kind: .weekly, duration: 7 * 24 * 60 * 60)
