167	  static func codexRollout(data: Data, fileSize: UInt64, modifiedAt: Date, now: Date)
168	    -> AgentQuotaSnapshot?
169	  {
170	    var bytes = data
171	    // A bounded tail can begin halfway through a JSONL record. Drop that fragment.
172	    if fileSize > UInt64(data.count), let newline = bytes.firstIndex(of: 0x0A) {
173	      bytes.removeSubrange(...newline)
174	    }
175	    for rawLine in bytes.split(separator: 0x0A, omittingEmptySubsequences: true).reversed() {
176	      guard
177	        let object = try? JSONSerialization.jsonObject(with: Data(rawLine)) as? [String: Any],
178	        let payload = object["payload"] as? [String: Any],
179	        payload["type"] as? String == "token_count",
180	        let limits = payload["rate_limits"] as? [String: Any]
181	      else { continue }
182	
183	      let capturedAt = (object["timestamp"] as? String).flatMap(parseISO8601) ?? modifiedAt
184	      var windows: [AgentQuotaWindow] = []
185	      for key in ["primary", "secondary"] {
186	        guard let value = limits[key] as? [String: Any],
187	          let minutes = number(value["window_minutes"]).map(Int.init), minutes > 0,
188	          let used = number(value["used_percent"])
189	        else { continue }
190	        let reset: Date?
191	        if let seconds = number(value["resets_at"]) {
192	          reset = Date(timeIntervalSince1970: seconds)
193	        } else if let remaining = number(value["resets_in_seconds"]) {
194	          reset = capturedAt.addingTimeInterval(remaining)
195	        } else {
196	          reset = nil
197	        }
198	        guard let reset else { continue }
199	        windows.append(
200	          AgentQuotaWindow(
201	            kind: kind(for: minutes), usedPercentage: used,
202	            duration: TimeInterval(minutes * 60), resetsAt: reset))
203	      }
204	      if let snapshot = normalized(.codex, windows: windows, capturedAt: capturedAt, now: now) {
205	        return snapshot
206	      }
207	    }
208	    return nil
209	  }
