211	  static func readCodexSnapshot(
212	    sessionsRoot: URL, now: Date, maximumTailBytes: Int = maximumTailBytes,
213	    fileManager: FileManager = .default
214	  ) -> AgentQuotaSnapshot? {
215	    guard
216	      let enumerator = fileManager.enumerator(
217	        at: sessionsRoot,
218	        includingPropertiesForKeys: [.isRegularFileKey, .contentModificationDateKey],
219	        options: [.skipsHiddenFiles, .skipsPackageDescendants])
220	    else { return nil }
221	    var candidates: [(URL, Date)] = []
222	    for case let url as URL in enumerator where url.pathExtension == "jsonl" {
223	      guard
224	        let values = try? url.resourceValues(forKeys: [
225	          .isRegularFileKey, .contentModificationDateKey,
226	        ]),
227	        values.isRegularFile == true
228	      else { continue }
229	      candidates.append((url, values.contentModificationDate ?? .distantPast))
230	    }
231	    // A malformed/partially-written newest rollout must not suppress a slightly older valid one.
232	    for (url, modifiedAt) in candidates.sorted(by: { $0.1 > $1.1 }).prefix(12) {
233	      guard let handle = try? FileHandle(forReadingFrom: url) else { continue }
234	      defer { try? handle.close() }
235	      let size = (try? handle.seekToEnd()) ?? 0
236	      let count = min(UInt64(maximumTailBytes), size)
237	      try? handle.seek(toOffset: size - count)
238	      guard let data = try? handle.read(upToCount: Int(count)), !data.isEmpty else { continue }
239	      if let snapshot = codexRollout(
240	        data: data, fileSize: size, modifiedAt: modifiedAt, now: now)
241	      {
242	        return snapshot
243	      }
244	    }
245	    return nil
246	  }
