12	enum SessionAttachClient {
13	  static let connectCycles = 3
14	  static let connectAttemptsPerCycle = 50
15	  static let connectRetryMicroseconds: useconds_t = 20000
16	  static let handshakeAttempts = 3
17	  static let handshakeRetryMicroseconds: useconds_t = 100_000
18	  static let inputBacklogLimit = 4 * 1024 * 1024
19	  /// How long after attaching to re-check the terminal size once more (seconds).
20	  ///
21	  /// A reattached session's redraw fires immediately on `.attached`, using whatever size THIS
22	  /// process's controlling pty reports at that instant — which, for a pane the host app spawns
23	  /// eagerly off-window at a placeholder size (so a restored session appears instantly instead of
24	  /// waiting for a click), is not yet the pane's real on-screen size. The host's own later resize
25	  /// SHOULD retrigger a correct redraw via the normal SIGWINCH path, but that depends on the
26	  /// signal actually landing after this process has armed its handler — a race on process
27	  /// startup. This settle re-check doesn't depend on catching any signal: it just re-reads the
28	  /// CURRENT size (already updated by the kernel regardless of whether we saw a SIGWINCH for it)
29	  /// once the host has almost certainly finished laying out the real pane, and resends it —
30	  /// closing that race unconditionally rather than hoping it doesn't occur.
31	  static let settleCheckDelaySeconds: Double = 0.3
32	
