61	  static func run(configuration: Configuration) -> Int32 {
62	    signal(SIGPIPE, SIG_IGN)
63	
64	    guard let signalPipe = SessionSignalPipe(signals: [SIGWINCH]) else {
65	      return SessionAttachExitCode.startupFailure
66	    }
67	
68	    let originalTerminal = enterRawMode()
69	    defer {
70	      if var originalTerminal {
71	        tcsetattr(STDIN_FILENO, TCSANOW, &originalTerminal)
72	      }
73	    }
74	
75	    for attempt in 0..<handshakeAttempts {
76	      switch attach(configuration: configuration, signalPipe: signalPipe) {
77	      case .finished(let status), .failed(let status):
78	        return status
79	      case .retry:
80	        if attempt + 1 < handshakeAttempts {
81	          usleep(handshakeRetryMicroseconds)
82	        }
83	      }
84	    }
85	
86	    report("could not reach the session daemon")
87	    return SessionAttachExitCode.daemonUnavailable
88	  }
