90	  private static func attach(configuration: Configuration, signalPipe: SessionSignalPipe) -> Outcome
91	  {
92	    let socket: Int32
93	    switch connect(socketPath: configuration.socketPath) {
94	    case .connected(let descriptor):
95	      socket = descriptor
96	    case .retry:
97	      return .retry
98	    case .failed(let status):
99	      return .failed(status)
100	    }
101	    defer { SessionIO.close(socket) }
102	    SessionIO.setNonBlocking(socket)
103	
104	    let payload = makeRequest(configuration).encoded()
105	    guard payload.count <= SessionFrame.maximumPayloadSize else {
106	      // Fail fast and specifically rather than retrying `handshakeAttempts` times against the
107	      // same oversized payload and reporting the generic, misleading "could not reach the
108	      // session daemon" — this is almost always a bloated shell environment (exported functions,
109	      // PATH bloat from asdf/direnv/nvm hooks), not a daemon problem.
110	      report(
111	        "attach request too large (\(payload.count) bytes, limit "
112	          + "\(SessionFrame.maximumPayloadSize)) — check for an oversized shell environment")
113	      return .failed(SessionAttachExitCode.protocolFailure)
114	    }
115	
116	    let connection = SessionConnection(descriptor: socket)
117	    connection.enqueue(SessionFrame(kind: .attach, payload: payload))
118	    return loop(connection: connection, signalPipe: signalPipe)
119	  }
