121	  private static func loop(connection: SessionConnection, signalPipe: SessionSignalPipe) -> Outcome
122	  {
123	    var isAttached = false
124	    var settleDeadline: Double?
125	    while true {
126	      guard connection.flush() else { return transportOutcome(isAttached: isAttached) }
127	
128	      var descriptors = [
129	        pollfd(fd: signalPipe.readDescriptor, events: Int16(POLLIN), revents: 0),
130	        pollfd(
131	          fd: connection.descriptor,
132	          events: Int16(
133	            connection.hasPendingOutput ? Int32(POLLIN) | Int32(POLLOUT) : Int32(POLLIN)),
134	          revents: 0),
135	      ]
136	      if isAttached, connection.pendingByteCount < inputBacklogLimit {
137	        descriptors.append(pollfd(fd: STDIN_FILENO, events: Int16(POLLIN), revents: 0))
138	      }
139	
140	      let ready = poll(&descriptors, nfds_t(descriptors.count), pollTimeout(until: settleDeadline))
141	      if ready == 0, let deadline = settleDeadline, SessionClock.monotonicSeconds() >= deadline {
142	        settleDeadline = nil
143	        sendResize(connection)
144	        continue
145	      }
146	      if ready < 0 {
147	        guard errno == EINTR else { return transportOutcome(isAttached: isAttached) }
148	        continue
149	      }
150	
151	      for entry in descriptors where entry.revents != 0 {
152	        if entry.fd == signalPipe.readDescriptor {
153	          signalPipe.drain()
154	          sendResize(connection)
155	        } else if entry.fd == STDIN_FILENO {
156	          guard forwardInput(connection) else { return .finished(0) }
157	        } else if let outcome = receive(connection, revents: entry.revents, isAttached: &isAttached)
158	        {
159	          _ = connection.flush()
160	          return outcome
161	        }
162	      }
163	      // Arm the one-shot settle re-check the moment `.attached` lands, not before — there's
164	      // nothing to settle until the daemon has actually accepted us.
165	      if isAttached, settleDeadline == nil {
166	        settleDeadline = SessionClock.monotonicSeconds() + settleCheckDelaySeconds
167	      }
168	    }
169	  }
170	
171	  /// `poll`'s timeout in milliseconds: bounded while a settle check is pending (so we wake up to
172	  /// fire it even with no other activity), `-1` (block indefinitely) once there's nothing to wait
173	  /// for — this is a single terminal session's I/O loop, not a busy-poll.
174	  private static func pollTimeout(until deadline: Double?) -> Int32 {
175	    guard let deadline else { return -1 }
176	    let remaining = deadline - SessionClock.monotonicSeconds()
177	    guard remaining > 0 else { return 0 }
178	    return Int32((remaining * 1000).rounded(.up))
179	  }
