185	  private static func forwardInput(_ connection: SessionConnection) -> Bool {
186	    switch SessionIO.read(STDIN_FILENO) {
187	    case .bytes(let bytes):
188	      connection.enqueue(SessionFrame(kind: .input, payload: bytes))
189	      return true
190	    case .wouldBlock:
191	      return true
192	    case .endOfFile, .failed:
193	      return false
194	    }
195	  }
196	
197	  private static func receive(
198	    _ connection: SessionConnection,
199	    revents: Int16,
200	    isAttached: inout Bool
201	  ) -> Outcome? {
202	    if revents & Int16(POLLOUT) != 0, !connection.flush() {
203	      return transportOutcome(isAttached: isAttached)
204	    }
205	    guard revents & Int16(POLLIN) != 0 || revents & Int16(POLLHUP) != 0 else { return nil }
206	
207	    var reachedEnd = false
208	    readLoop: while true {
209	      switch SessionIO.read(connection.descriptor) {
210	      case .bytes(let bytes):
211	        connection.decoder.push(bytes)
212	      case .wouldBlock:
213	        break readLoop
214	      case .endOfFile, .failed:
215	        reachedEnd = true
216	        break readLoop
217	      }
218	    }
219	
220	    while true {
221	      let frame: SessionFrame?
222	      do {
223	        frame = try connection.decoder.next()
224	      } catch {
225	        return .failed(SessionAttachExitCode.protocolFailure)
226	      }
227	      guard let frame else { break }
228	      switch frame.kind {
229	      case .attached:
230	        isAttached = true
231	      case .output:
232	        guard SessionIO.writeAll(STDOUT_FILENO, frame.payload) else {
233	          return transportOutcome(isAttached: isAttached)
234	        }
235	      case .exited:
236	        return .finished((try? SessionExitPayload.decode(frame.payload)) ?? 0)
237	      case .failure:
238	        report((try? SessionTextPayload.decode(frame.payload)) ?? "session failed")
239	        return .failed(SessionAttachExitCode.protocolFailure)
240	      case .attach, .input, .resize, .list, .info, .kill, .killAll, .sessions, .acknowledged:
241	        break
242	      }
243	    }
244	
245	    return reachedEnd ? transportOutcome(isAttached: isAttached) : nil
246	  }
