289	  private static func connect(socketPath: String) -> ConnectionOutcome {
290	    for _ in 0..<connectCycles {
291	      if let descriptor = SessionSocket.connect(path: socketPath) {
292	        return .connected(descriptor)
293	      }
294	      switch launchDaemon(socketPath: socketPath) {
295	      case .started, .retryableFailure:
296	        break
297	      case .fatalFailure:
298	        return .failed(SessionAttachExitCode.startupFailure)
299	      }
300	      for _ in 0..<connectAttemptsPerCycle {
301	        usleep(connectRetryMicroseconds)
302	        if let descriptor = SessionSocket.connect(path: socketPath) {
303	          return .connected(descriptor)
304	        }
305	      }
306	    }
307	    return .retry
308	  }
