310	  private static func launchDaemon(socketPath: String) -> DaemonLaunchOutcome {
311	    guard let binaryPath = executablePath() else {
312	      report("unable to locate the session daemon binary")
313	      return .fatalFailure
314	    }
315	    let arguments = SessionCStringArray([binaryPath, "daemon", "--socket", socketPath])
316	
317	    var fileActions: posix_spawn_file_actions_t?
318	    posix_spawn_file_actions_init(&fileActions)
319	    defer { posix_spawn_file_actions_destroy(&fileActions) }
320	    posix_spawn_file_actions_addopen(&fileActions, STDIN_FILENO, "/dev/null", O_RDWR, 0)
321	    posix_spawn_file_actions_addopen(&fileActions, STDOUT_FILENO, "/dev/null", O_RDWR, 0)
322	    posix_spawn_file_actions_addopen(
323	      &fileActions,
324	      STDERR_FILENO,
325	      socketPath + ".log",
326	      O_WRONLY | O_CREAT | O_APPEND | O_NOFOLLOW,
327	      0o600)
328	
329	    var attributes: posix_spawnattr_t?
330	    posix_spawnattr_init(&attributes)
331	    defer { posix_spawnattr_destroy(&attributes) }
332	    posix_spawnattr_setflags(&attributes, Int16(POSIX_SPAWN_SETSID))
333	
334	    var processID: pid_t = 0
335	    let result = posix_spawn(
336	      &processID, binaryPath, &fileActions, &attributes, arguments.pointer, environ)
337	    guard result != 0 else { return .started }
338	    report("could not start the session daemon (\(result))")
339	    return result == EAGAIN || result == EINTR ? .retryableFailure : .fatalFailure
340	  }
