342	  static func executablePath() -> String? {
343	    if let provided = SessionProcessEnvironment.value("WORKROOM_SESSION_BINARY") {
344	      return provided
345	    }
346	    var size = UInt32(PATH_MAX)
347	    var buffer = [CChar](repeating: 0, count: Int(PATH_MAX))
348	    guard _NSGetExecutablePath(&buffer, &size) == 0 else { return nil }
349	    return buffer.withUnsafeBufferPointer { pointer in
350	      guard let base = pointer.baseAddress else { return nil }
351	      return String(cString: base)
352	    }
353	  }
