2	import WorkroomSessionProtocol
3	
4	struct SessionProcess {
5	  let masterDescriptor: Int32
6	  let processID: pid_t
7	  let ttyDevice: UInt64
8	}
9	
10	enum SessionPTY {
11	  private static let resetSignals: [Int32] = [
12	    SIGPIPE, SIGCHLD, SIGHUP, SIGINT, SIGQUIT, SIGTERM, SIGTSTP, SIGTTIN, SIGTTOU,
13	  ]
14	  private static let terminationPollMicroseconds: useconds_t = 10000
15	  private static let gracefulTerminationAttempts = 20
16	  private static let forcedTerminationAttempts = 50
17	
18	  static func spawn(
19	    invocation: SessionShellInvocation,
20	    workingDirectory: String,
21	    columns: UInt16,
22	    rows: UInt16
23	  ) -> SessionProcess? {
24	    let argumentList = SessionCStringArray(invocation.arguments)
25	    let environmentList = SessionCStringArray(
26	      invocation.environment.map { "\($0.key)=\($0.value)" })
27	    guard let executable = strdup(invocation.executable) else { return nil }
28	    let directory = strdup(workingDirectory)
29	    defer {
30	      free(executable)
31	      free(directory)
32	    }
33	
34	    var size = winsize(
35	      ws_row: rows == 0 ? 24 : rows,
36	      ws_col: columns == 0 ? 80 : columns,
37	      ws_xpixel: 0,
38	      ws_ypixel: 0)
39	    var master: Int32 = -1
40	    var name = [CChar](repeating: 0, count: Int(PATH_MAX))
41	
42	    let processID = forkpty(&master, &name, nil, &size)
43	    if processID < 0 {
44	      SessionLog.write("forkpty failed: \(String(cString: strerror(errno)))")
45	      return nil
46	    }
47	
48	    if processID == 0 {
49	      var empty = sigset_t()
50	      sigemptyset(&empty)
51	      sigprocmask(SIG_SETMASK, &empty, nil)
52	      for number in resetSignals {
53	        signal(number, SIG_DFL)
54	      }
55	      if let directory, chdir(directory) != 0 {
56	        if let home = getenv("HOME") {
57	          _ = chdir(home)
58	        } else {
59	          _ = chdir("/")
60	        }
61	      }
62	      execve(executable, argumentList.pointer, environmentList.pointer)
63	      _exit(127)
64	    }
65	
66	    SessionIO.setNonBlocking(master)
67	    SessionIO.setCloseOnExec(master)
68	
69	    var status = stat()
70	    let device: UInt64 =
71	      stat(&name, &status) == 0
72	      ? UInt64(UInt32(bitPattern: status.st_rdev))
73	      : 0
74	
75	    return SessionProcess(masterDescriptor: master, processID: processID, ttyDevice: device)
76	  }
77	
78	  static func resize(masterDescriptor: Int32, columns: UInt16, rows: UInt16) {
79	    var size = winsize(
80	      ws_row: rows == 0 ? 24 : rows,
81	      ws_col: columns == 0 ? 80 : columns,
82	      ws_xpixel: 0,
83	      ws_ypixel: 0)
84	    _ = ioctl(masterDescriptor, TIOCSWINSZ, &size)
85	  }
86	
87	  static func windowSize(descriptor: Int32) -> (columns: UInt16, rows: UInt16)? {
88	    var size = winsize()
89	    guard ioctl(descriptor, TIOCGWINSZ, &size) == 0 else { return nil }
90	    return (size.ws_col, size.ws_row)
91	  }
92	
93	  static func foregroundProcessGroup(masterDescriptor: Int32) -> pid_t? {
94	    let group = tcgetpgrp(masterDescriptor)
95	    return group > 0 ? group : nil
96	  }
97	
98	  /// Row count to bump a pty to, transiently, to force an observable size delta.
99	  ///
100	  /// A bare `SIGWINCH` is not enough to make a full-screen program repaint on reattach: the pty's
101	  /// real size is already correct (it never changed while the session sat alive in the
102	  /// background), so a program that checks "did the terminal size actually change" before
103	  /// repainting — observed with Claude Code; Codex repaints regardless — silently ignores it,
104	  /// leaving the new client showing stale primary-screen content underneath the (unpainted)
105	  /// alternate screen until a genuine later resize forces a real delta.
106	  ///
107	  /// Bumping the row count down (or up, at the 1-row floor) then back — the same trick tmux/screen
108	  /// use to force a client redraw on attach — guarantees the child observes an actual size
109	  /// transition either way. Pure arithmetic only: the daemon owns *when* to resize back and signal
110	  /// (`SessionDaemon`'s deferred redraw scheduling), since giving the child time to actually observe
111	  /// the transient size before reverting it needs a real delay — and this single-threaded daemon
112	  /// serves every session across every open project, so that delay must not block its poll loop.
113	  static func bumpedRowCount(_ rows: UInt16) -> UInt16 {
114	    rows > 1 ? rows - 1 : rows + 1
115	  }
116	
117	  static func requestRedraw(masterDescriptor: Int32, fallbackProcessID: pid_t) {
118	    let group = foregroundProcessGroup(masterDescriptor: masterDescriptor) ?? fallbackProcessID
119	    guard group > 0 else { return }
120	    _ = killpg(group, SIGWINCH)
121	  }
122	
123	  static func terminate(processID: pid_t) {
124	    guard processID > 0 else { return }
125	    if killpg(processID, SIGHUP) != 0 {
126	      _ = kill(processID, SIGHUP)
127	    }
128	    _ = killpg(processID, SIGCONT)
129	  }
130	
131	  static func forceTerminate(processID: pid_t) -> Bool {
132	    forceTerminate(processIDs: [processID]).isEmpty
133	  }
134	
135	  static func forceTerminate(processIDs: [pid_t]) -> Set<pid_t> {
136	    let targets = Set(processIDs.filter { $0 > 0 })
137	    guard !targets.isEmpty else { return [] }
138	
139	    signalSessions(targets, signal: SIGTERM)
140	    let resistant = waitForSessionsExit(targets, attempts: gracefulTerminationAttempts)
141	    guard !resistant.isEmpty else { return [] }
142	
143	    signalSessions(resistant, signal: SIGKILL)
144	    return waitForSessionsExit(
145	      resistant, attempts: forcedTerminationAttempts, repeatedSignal: SIGKILL)
146	  }
147	
148	  private static func signalSessions(_ sessionIDs: Set<pid_t>, signal: Int32) {
149	    guard let members = sessionProcessIDs(sessionIDs: sessionIDs) else {
150	      for sessionID in sessionIDs {
151	        _ = killpg(sessionID, signal)
152	        _ = kill(sessionID, signal)
153	      }
154	      return
155	    }
156	    signalSessions(sessionIDs, members: members, signal: signal)
157	  }
158	
159	  private static func signalSessions(
160	    _ sessionIDs: Set<pid_t>, members: [pid_t: [pid_t]], signal: Int32
161	  ) {
162	    for sessionID in sessionIDs {
163	      let memberProcessIDs = members[sessionID] ?? []
164	      if memberProcessIDs.isEmpty {
165	        _ = kill(sessionID, signal)
166	        continue
167	      }
168	      for memberProcessID in memberProcessIDs {
169	        _ = kill(memberProcessID, signal)
170	      }
171	    }
172	  }
173	
174	  private static func waitForSessionsExit(
175	    _ sessionIDs: Set<pid_t>,
176	    attempts: Int,
177	    repeatedSignal: Int32? = nil
178	  ) -> Set<pid_t> {
179	    var remaining = sessionIDs
180	    for _ in 0..<attempts {
181	      reap(processIDs: remaining)
182	      guard let members = sessionProcessIDs(sessionIDs: remaining) else {
183	        usleep(terminationPollMicroseconds)
184	        continue
185	      }
186	      remaining = activeSessionIDs(remaining, members: members)
187	      guard !remaining.isEmpty else { return [] }
188	      if let repeatedSignal {
189	        signalSessions(remaining, members: members, signal: repeatedSignal)
190	      }
191	      usleep(terminationPollMicroseconds)
192	    }
193	
194	    reap(processIDs: remaining)
195	    guard let members = sessionProcessIDs(sessionIDs: remaining) else { return remaining }
196	    return activeSessionIDs(remaining, members: members)
197	  }
198	
199	  private static func activeSessionIDs(_ sessionIDs: Set<pid_t>, members: [pid_t: [pid_t]])
200	    -> Set<pid_t>
201	  {
202	    sessionIDs.filter { processExists($0) || !(members[$0] ?? []).isEmpty }
203	  }
204	
205	  private static func reap(processIDs: Set<pid_t>) {
206	    for processID in processIDs {
207	      var status: Int32 = 0
208	      while waitpid(processID, &status, WNOHANG) < 0, errno == EINTR {}
209	    }
210	  }
211	
212	  private static func processExists(_ processID: pid_t) -> Bool {
213	    guard kill(processID, 0) != 0 else { return true }
214	    return errno == EPERM
215	  }
216	
217	  private static func sessionProcessIDs(sessionIDs: Set<pid_t>) -> [pid_t: [pid_t]]? {
218	    let stride = MemoryLayout<kinfo_proc>.stride
219	    for _ in 0..<3 {
220	      var name: [Int32] = [CTL_KERN, KERN_PROC, KERN_PROC_ALL]
221	      var size = 0
222	      guard sysctl(&name, 3, nil, &size, nil, 0) == 0, size > 0 else { return nil }
223	
224	      var records = [kinfo_proc](repeating: kinfo_proc(), count: size / stride + 16)
225	      size = records.count * stride
226	      if sysctl(&name, 3, &records, &size, nil, 0) != 0 {
227	        guard errno == ENOMEM else { return nil }
228	        continue
229	      }
230	
231	      var members: [pid_t: [pid_t]] = [:]
232	      for record in records.prefix(size / stride) {
233	        let processID = record.kp_proc.p_pid
234	        guard processID > 0 else { continue }
235	        let sessionID = getsid(processID)
236	        guard sessionIDs.contains(sessionID) else { continue }
237	        members[sessionID, default: []].append(processID)
238	      }
239	      return members
240	    }
241	    return nil
242	  }
243	}
