4	enum SessionDaemonStart {
5	  case running(SessionDaemon)
6	  case lockHeld
7	  case failed(String)
8	}
9	
10	final class SessionDaemon {
11	  static let replayCapacity = 256 * 1024
12	  static let clientOutputLimit = 4 * 1024 * 1024
13	  static let sessionInputLimit = 1024 * 1024
14	  static let maximumConnections = 64
15	  static let maximumSessions = 256
16	  static let idleTimeoutMilliseconds: Int32 = 10000
17	  static let replayChunkSize = 32 * 1024
18	  /// How long to leave a reattached session's pty bumped before resizing it back and signaling —
19	  /// long enough for the child to actually be scheduled and observe the transient size (see
20	  /// `SessionPTY.bumpedRowCount`), short enough nobody notices. Deferred through the poll loop
21	  /// rather than a blocking sleep: this daemon is single-threaded and serves every session across
22	  /// every open project, so blocking here would freeze all of them for the duration, worst-case
23	  /// stacking to N × this value when many persisted tabs reattach at once on relaunch.
24	  static let redrawSettleSeconds: Double = 0.03
25	
26	  private let socketPath: String
27	  private let idleTimeout: Int32
28	  private let listener: Int32
29	  private let lockDescriptor: Int32
30	  private let signalPipe: SessionSignalPipe
31	
32	  private var sessions: [SessionIdentifier: PTYSession] = [:]
33	  private var sessionsByMaster: [Int32: SessionIdentifier] = [:]
34	  private var connections: [Int32: SessionConnection] = [:]
35	  private var closingDescriptors: [Int32] = []
36	  /// Sessions bumped by `attach()`, awaiting their non-blocking resize-back-and-signal once
37	  /// `redrawSettleSeconds` has elapsed. Keyed by identifier, not master fd, so a session that gets
38	  /// killed and its fd reused before the deadline can't cause this to resize/signal the WRONG pty.
39	  private var pendingRedraws: [SessionIdentifier: PendingRedraw] = [:]
40	
41	  private struct PendingRedraw {
42	    let deadline: Double
43	    let columns: UInt16
44	    let rows: UInt16
45	  }
46	
47	  static func start(
48	    socketPath: String,
49	    idleTimeoutMilliseconds: Int32 = SessionDaemon.idleTimeoutMilliseconds
50	  ) -> SessionDaemonStart {
51	    signal(SIGPIPE, SIG_IGN)
52	    signal(SIGHUP, SIG_IGN)
53	
54	    guard let lock = SessionSocket.acquireLock(path: socketPath + ".lock") else {
55	      return .lockHeld
56	    }
57	    guard let signalPipe = SessionSignalPipe(signals: [SIGCHLD]) else {
58	      SessionIO.close(lock)
59	      return .failed("unable to create the signal pipe")
60	    }
61	    guard let listener = SessionSocket.makeListener(path: socketPath) else {
62	      SessionIO.close(lock)
63	      return .failed("unable to listen on \(socketPath)")
64	    }
65	    return .running(
66	      SessionDaemon(
67	        socketPath: socketPath,
68	        idleTimeout: idleTimeoutMilliseconds,
69	        listener: listener,
70	        lockDescriptor: lock,
71	        signalPipe: signalPipe))
72	  }
73	
74	  private init(
75	    socketPath: String,
76	    idleTimeout: Int32,
77	    listener: Int32,
78	    lockDescriptor: Int32,
79	    signalPipe: SessionSignalPipe
80	  ) {
81	    self.socketPath = socketPath
82	    self.idleTimeout = idleTimeout
83	    self.listener = listener
84	    self.lockDescriptor = lockDescriptor
85	    self.signalPipe = signalPipe
86	  }
87	
88	  func run() {
89	    while true {
90	      let isIdle = sessions.isEmpty && connections.isEmpty
91	      var descriptors = buildPollDescriptors()
92	      let ready = poll(&descriptors, nfds_t(descriptors.count), pollTimeout(isIdle: isIdle))
93	      if ready == 0 {
94	        if processExpiredRedraws() { continue }
95	        guard sessions.isEmpty, connections.isEmpty else { continue }
96	        acceptConnections()
97	        guard connections.isEmpty else { continue }
98	        break
99	      }
100	      if ready < 0 {
101	        switch errno {
102	        case EINTR, EAGAIN, ENOMEM:
103	          continue
104	        default:
105	          SessionLog.write("poll failed: \(String(cString: strerror(errno)))")
106	          break
107	        }
108	        break
109	      }
110	      handle(descriptors)
111	      processExpiredRedraws()
112	      reapChildren()
113	      flushConnections()
114	      closeMarkedConnections()
115	    }
116	    shutdown()
117	  }
118	
119	  /// The nearest pending redraw's deadline overrides the ordinary idle/-1 timeout whenever one is
120	  /// outstanding, so the loop wakes up to resize-back-and-signal even with no other activity —
121	  /// without ever blocking inside a `usleep` the way the redraw used to.
122	  private func pollTimeout(isIdle: Bool) -> Int32 {
123	    guard let nearest = pendingRedraws.values.map(\.deadline).min() else {
124	      return isIdle ? idleTimeout : -1
125	    }
126	    let remainingMilliseconds = (nearest - SessionClock.monotonicSeconds()) * 1000
127	    return Int32(max(0, remainingMilliseconds.rounded(.up)))
128	  }
129	
130	  /// Resize each expired pending redraw back to its real size and signal, non-blockingly. Collects
131	  /// expired keys into a copy first — mutating `pendingRedraws` while iterating it directly is
132	  /// unsafe. A session that died before its deadline is silently dropped: nothing to resize.
133	  @discardableResult
134	  private func processExpiredRedraws() -> Bool {
135	    guard !pendingRedraws.isEmpty else { return false }
136	    let now = SessionClock.monotonicSeconds()
137	    let expired = pendingRedraws.filter { $0.value.deadline <= now }
138	    guard !expired.isEmpty else { return false }
139	    for (identifier, pending) in expired {
140	      pendingRedraws.removeValue(forKey: identifier)
141	      guard let session = sessions[identifier] else { continue }
142	      SessionPTY.resize(
143	        masterDescriptor: session.masterDescriptor, columns: pending.columns, rows: pending.rows)
144	      SessionPTY.requestRedraw(
145	        masterDescriptor: session.masterDescriptor, fallbackProcessID: session.processID)
146	    }
147	    return true
148	  }
149	
150	  private func shutdown() {
151	    for session in Array(sessions.values) {
152	      closeMaster(session)
153	    }
154	    for descriptor in connections.keys {
155	      SessionIO.close(descriptor)
156	    }
157	    SessionIO.close(listener)
158	    unlink(socketPath)
159	    // Deliberately NOT unlinking the lock file: closing this descriptor releases the flock on
160	    // its inode, but the path stays put so the next daemon's `acquireLock` opens the SAME inode
161	    // and re-flocks it. Unlinking here would leave a window where the path still exists but is
162	    // unlocked — a racing daemon could open+flock that inode before we unlink it, and a THIRD
163	    // daemon started after our unlink would then create a brand-new inode and also succeed,
164	    // leaving two daemons simultaneously believing they're the sole instance.
165	    SessionIO.close(lockDescriptor)
166	  }
167	
168	  private func buildPollDescriptors() -> [pollfd] {
169	    var descriptors: [pollfd] = [
170	      pollfd(fd: listener, events: Int16(POLLIN), revents: 0),
171	      pollfd(fd: signalPipe.readDescriptor, events: Int16(POLLIN), revents: 0),
172	    ]
173	    for connection in connections.values {
174	      var events = Int32(POLLIN)
175	      if connection.hasPendingOutput { events |= Int32(POLLOUT) }
176	      descriptors.append(pollfd(fd: connection.descriptor, events: Int16(events), revents: 0))
177	    }
178	    for session in sessions.values where session.masterDescriptor >= 0 {
179	      var events: Int32 = 0
180	      if !isClientBackedUp(session) { events |= Int32(POLLIN) }
181	      if session.hasPendingInput { events |= Int32(POLLOUT) }
182	      guard events != 0 else { continue }
183	      descriptors.append(pollfd(fd: session.masterDescriptor, events: Int16(events), revents: 0))
184	    }
185	    return descriptors
186	  }
187	
188	  private func isClientBackedUp(_ session: PTYSession) -> Bool {
189	    guard let descriptor = session.clientDescriptor,
190	      let connection = connections[descriptor]
191	    else { return false }
192	    return connection.pendingByteCount >= Self.clientOutputLimit
193	  }
194	
195	  private func handle(_ descriptors: [pollfd]) {
196	    for entry in descriptors where entry.revents != 0 {
197	      if entry.fd == listener {
198	        acceptConnections()
199	      } else if entry.fd == signalPipe.readDescriptor {
200	        signalPipe.drain()
201	      } else if connections[entry.fd] != nil {
202	        handleConnection(entry)
203	      } else if let identifier = sessionsByMaster[entry.fd] {
204	        handleMaster(entry, identifier: identifier)
205	      }
206	    }
207	  }
208	
209	  private func acceptConnections() {
210	    while let descriptor = SessionSocket.accept(listener) {
211	      guard connections.count < Self.maximumConnections else {
212	        SessionIO.close(descriptor)
213	        continue
214	      }
215	      guard SessionSocket.peerUserID(descriptor) == getuid() else {
216	        SessionLog.write("rejected connection from another user")
217	        SessionIO.close(descriptor)
218	        continue
219	      }
220	      connections[descriptor] = SessionConnection(descriptor: descriptor)
221	    }
222	  }
223	
224	  private func handleConnection(_ entry: pollfd) {
225	    guard let connection = connections[entry.fd] else { return }
226	    if entry.revents & Int16(POLLOUT) != 0, !connection.flush() {
227	      markForClose(entry.fd)
228	      return
229	    }
230	    guard entry.revents & Int16(POLLIN) != 0 || entry.revents & Int16(POLLHUP) != 0 else { return }
231	
232	    var reachedEnd = false
233	    readLoop: while true {
234	      switch SessionIO.read(entry.fd) {
235	      case .bytes(let bytes):
236	        connection.decoder.push(bytes)
237	      case .wouldBlock:
238	        break readLoop
239	      case .endOfFile, .failed:
240	        reachedEnd = true
241	        break readLoop
242	      }
243	    }
244	
245	    while true {
246	      do {
247	        guard let frame = try connection.decoder.next() else { break }
248	        handle(frame: frame, connection: connection)
249	      } catch {
250	        SessionLog.write("dropping connection with a malformed frame")
251	        markForClose(entry.fd)
252	        return
253	      }
254	    }
255	
256	    if reachedEnd { markForClose(entry.fd) }
257	  }
258	
259	  private func handle(frame: SessionFrame, connection: SessionConnection) {
260	    switch frame.kind {
261	    case .attach:
262	      handleAttach(payload: frame.payload, connection: connection)
263	    case .input:
264	      guard let identifier = connection.attachedSession, let session = sessions[identifier] else {
265	        return
266	      }
267	      session.appendInput(frame.payload, limit: Self.sessionInputLimit)
268	      session.flushInput()
269	    case .resize:
270	      guard let identifier = connection.attachedSession,
271	        let session = sessions[identifier],
272	        let size = try? SessionResizePayload.decode(frame.payload)
273	      else { return }
274	      guard SessionWindowSizePolicy.isUsable(columns: size.columns, rows: size.rows) else { return }
275	      SessionPTY.resize(
276	        masterDescriptor: session.masterDescriptor, columns: size.columns, rows: size.rows)
277	    case .list:
278	      connection.enqueue(
279	        SessionFrame(
280	          kind: .sessions,
281	          payload: SessionDescriptor.encodeList(sessions.values.map(\.descriptor))))
282	    case .info:
283	      guard let identifier = try? SessionIdentifierPayload.decode(frame.payload) else { return }
284	      let matches = sessions[identifier].map { [$0.descriptor] } ?? []
285	      connection.enqueue(
286	        SessionFrame(kind: .sessions, payload: SessionDescriptor.encodeList(matches)))
287	    case .kill:
288	      let stopped: Bool
289	      if let identifier = try? SessionIdentifierPayload.decode(frame.payload),
290	        let session = sessions[identifier]
291	      {
292	        stopped = endSession(session, status: 0, force: true)
293	      } else {
294	        stopped = true
295	      }
296	      enqueueStopResult(stopped, connection: connection)
297	    case .killAll:
298	      enqueueStopResult(endSessions(Array(sessions.values), status: 0), connection: connection)
299	    case .attached, .output, .exited, .failure, .sessions, .acknowledged:
300	      break
301	    }
302	  }
303	
304	  private func handleAttach(payload: [UInt8], connection: SessionConnection) {
305	    guard let request = try? SessionAttachRequest.decode(payload) else {
306	      connection.enqueue(
307	        SessionFrame(
308	          kind: .failure, payload: SessionTextPayload.encode("malformed attach request")))
309	      connection.closesAfterFlush = true
310	      return
311	    }
312	    guard request.version == SessionProtocolVersion.current else {
313	      connection.enqueue(
314	        SessionFrame(
315	          kind: .failure,
316	          payload: SessionTextPayload.encode(
317	            "this background session is owned by a different version of Workroom; stop it to start a new one"
318	          )))
319	      connection.closesAfterFlush = true
320	      return
321	    }
322	    guard connection.attachedSession == nil else { return }
323	
324	    if let session = sessions[request.identifier] {
325	      attach(session: session, request: request, connection: connection)
326	      return
327	    }
328	    create(request: request, connection: connection)
