/// or nil if unknown. The title a reattaching client sees is normally set once by the shell's
/// preexec hook right before it exec'd this program — a one-shot escape sequence emitted on the
/// PRIMARY screen, before the foreground program (typically) switches to the alternate screen.
/// `SessionReplayBuffer` drops its buffer the moment the alternate screen activates, so that title
/// is gone by the time a client reattaches, and the foreground program has no reason to re-emit
/// it on the redraw `requestRedraw` forces. Resolving it fresh here lets the daemon synthesize a
/// replacement (see `SessionDaemon.attach`) instead of leaving a reattached pane's title/agent
/// detection stuck at its stale pre-detach value.
static func foregroundExecutableName(masterDescriptor: Int32) -> String? {
  guard let group = foregroundProcessGroup(masterDescriptor: masterDescriptor) else { return nil }
  var name = [CChar](repeating: 0, count: Int(MAXPATHLEN))
  guard proc_name(group, &name, UInt32(name.count)) > 0 else { return nil }
  return String(cString: name)
}

